PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, assessment_type TEXT NOT NULL, source_day_id INTEGER REFERENCES curriculum_days(id) ON DELETE SET NULL, source_week_number INTEGER CHECK(source_week_number IS NULL OR source_week_number>=1), parent_assessment_id INTEGER REFERENCES assessments(id) ON DELETE SET NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number>=1), max_score REAL NOT NULL CHECK(max_score>0), score REAL NOT NULL CHECK(score>=0 AND score<=max_score), is_independent INTEGER NOT NULL CHECK(is_independent IN(0,1)), status TEXT NOT NULL CHECK(status IN('PASS','REPAIR_REQUIRED','RECORDED')), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_errors (id INTEGER PRIMARY KEY AUTOINCREMENT, assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', repair_required INTEGER NOT NULL DEFAULT 0 CHECK(repair_required IN(0,1)));
CREATE TABLE IF NOT EXISTS evidence (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL CHECK(length(trim(title))>0), description TEXT NOT NULL DEFAULT '', evidence_type TEXT NOT NULL, day_id INTEGER REFERENCES curriculum_days(id) ON DELETE SET NULL, week_number INTEGER CHECK(week_number IS NULL OR week_number>=1), location_or_url TEXT, confidence TEXT NOT NULL DEFAULT 'MEDIUM' CHECK(confidence IN('LOW','MEDIUM','HIGH')), verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN(0,1)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_evidence (assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, evidence_id INTEGER NOT NULL REFERENCES evidence(id) ON DELETE CASCADE, PRIMARY KEY(assessment_id,evidence_id));
CREATE TABLE IF NOT EXISTS repair_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, source_day_id INTEGER REFERENCES curriculum_days(id) ON DELETE SET NULL, source_block_id INTEGER REFERENCES curriculum_blocks(id) ON DELETE SET NULL, assessment_id INTEGER REFERENCES assessments(id) ON DELETE SET NULL, reason TEXT NOT NULL, priority TEXT NOT NULL, dependency_risk TEXT NOT NULL DEFAULT 'MEDIUM', status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','ACCEPTED','RESOLVED','DISMISSED')), scheduled_day_id INTEGER REFERENCES curriculum_days(id) ON DELETE SET NULL, created_at TEXT NOT NULL, completed_at TEXT, resolution_note TEXT);
CREATE TABLE IF NOT EXISTS activity_history (id INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, summary TEXT NOT NULL, created_at TEXT NOT NULL);
